insert into public.species (slug, name, latin, category_id, kind, difficulty, temperament, description, facts, keywords, is_rare) values
  ('labidochromis-caeruleus', 'Yellow Lab', 'Labidochromis caeruleus', 'malawi', 'fish', 'Kolay', 'Yarı agresif', 'Parlak sarı rengiyle Malawi tanklarının en sakin mbuna türlerinden biri. Bol kayalı düzen ve kalabalık stokla iyi geçinir.', '[["Yetişkin boy","10 cm"],["Sıcaklık","24–27 °C"],["pH","7.5–8.5"],["Min. akvaryum","200 L"],["Huy","Yarı agresif"],["Beslenme","Omnivor"],["Üreme","Ağız kuluçkacı"],["Köken","Malawi Gölü"],["Ömür","8–10 yıl"]]'::jsonb, array['yellow lab', 'labidochromis']::text[], false),
  ('chindongo-demasoni', 'Demasoni', 'Chindongo demasoni', 'malawi', 'fish', 'Orta', 'Agresif', 'Küçük ama kendi türüne karşı çok saldırgan. Saldırganlığı dağıtmak için 12+ bireylik gruplar halinde tutulması önerilir.', '[["Yetişkin boy","8 cm"],["Sıcaklık","24–27 °C"],["pH","7.5–8.6"],["Min. akvaryum","200 L"],["Huy","Agresif"],["Beslenme","Otçul ağırlıklı omnivor"],["Üreme","Ağız kuluçkacı"],["Köken","Malawi Gölü"],["Ömür","8–10 yıl"]]'::jsonb, array['demasoni']::text[], false),
