  ('metriaclima-estherae', 'Red Zebra', 'Metriaclima estherae', 'malawi', 'fish', 'Kolay', 'Agresif', 'Turuncu-pembe dişileri ve mavimsi erkekleriyle bilinen dayanıklı bir mbuna. Yüksek proteinli yemlerden kaçının.', '[["Yetişkin boy","12 cm"],["Sıcaklık","24–27 °C"],["pH","7.5–8.5"],["Min. akvaryum","300 L"],["Huy","Agresif"],["Beslenme","Otçul ağırlıklı omnivor"],["Üreme","Ağız kuluçkacı"],["Köken","Malawi Gölü"],["Ömür","8–10 yıl"]]'::jsonb, array['red zebra', 'estherae']::text[], false),
  ('neolamprologus-brichardi', 'Brichardi (Peri Prenses)', 'Neolamprologus brichardi', 'tanganyika', 'fish', 'Kolay', 'Yarı agresif (bölgesel)', 'Koloni halinde yaşar; önceki yavrular yeni kuşağın bakımına yardım eder. Bol kaya ve mağara ister.', '[["Yetişkin boy","9 cm"],["Sıcaklık","24–27 °C"],["pH","8–9"],["Min. akvaryum","150 L"],["Huy","Yarı agresif (bölgesel)"],["Beslenme","Omnivor"],["Üreme","Kaya yumurtlayıcı, koloni"],["Köken","Tanganyika Gölü"],["Ömür","8–10 yıl"]]'::jsonb, array['brichardi']::text[], false),
